using ModelContextProtocol.Server;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithTools<WeatherTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

// --- Tools ---

public static class WeatherTools
{
    [McpServerTool(Name = "get_weather"), Description("Gets the current weather for a city.")]
    public static string GetWeather(string city) =>
        $"The weather in {city} is 72°F and sunny.";
}

// --- Resources ---

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app_settings",
        Title = "Application Settings", MimeType = "application/json")]
    public static string GetAppSettings() =>
        """
        {
          "appName": "McpHttpServer",
          "version": "1.0.0",
          "features": {
            "darkMode": true,
            "maxRetries": 3,
            "timeoutSeconds": 30
          }
        }
        """;

    [McpServerResource(UriTemplate = "config://app/endpoints/{service}", Name = "service_endpoint",
        Title = "Service Endpoint Config", MimeType = "application/json")]
    public static string GetServiceEndpoint(string service) =>
        $$"""
        {
          "service": "{{service}}",
          "baseUrl": "https://{{service}}.internal.example.com",
          "healthCheck": "/health",
          "timeout": 5000
        }
        """;
}

