     [McpServerResource(UriTemplate = "config://app/settings", Name = "app_settings",
         Title = "Application Settings", MimeType = "application/json")]
     public static string GetAppSettings() =>
         """
         {
           "appName": "McpHttpServer",
           "version": "1.0.0",
           "features": {
             "darkMode": true,
             "maxRetries": 3,
             "timeoutSeconds": 30
           }
         }
         """;

     [McpServerResource(UriTemplate = "config://app/endpoints/{service}", Name = "service_endpoint",
         Title = "Service Endpoint Config", MimeType = "application/json")]
     public static string GetServiceEndpoint(string service) =>
         $$"""
         {
           "service": "{{service}}",
           "baseUrl": "https://{{service}}.internal.example.com",
           "healthCheck": "/health",
           "timeout": 5000
         }
         """;
 }
